package com.bare.wifi; public final class WifiDeviceAccess { public enum Source{LEGACY,ROOT,SHIZUKU,NONE} private final Source source; private final boolean available; public WifiDeviceAccess(Source source,boolean available){if(source==null)throw new IllegalArgumentException("source");this.source=source;this.available=available;} public Source getSource(){return source;} public boolean isAvailable(){return available;} }